    "Script": "FormManagement = {
    init: function (app) {
		if(!app) { app = session.app; }
        var root = $(".component[name=Forms]");
        var config = { 
			endpoint: "Core/Form", 
			filter: {
				logic: "and",
				filters: [
					{ field: "AppId", operator: "eq", value: app.Id }
				]
			} 
		};

		model.getDatasource(config, function (ds) {
			var grid = $("[name=grid]", root).kendoGrid({
				dataSource: ds,
				editable: true,
				sortable: true,
				filterable: true,
				pageable: {
					refresh: true,
					pageSizes: true,
					buttonCount: 5
				},
				toolbar: kendo.template("<div><button name='create'><span class='k-icon k-i-plus'></span>New</button></div>"),
				columns: [
					"Name",
					"RootMetaItem",
					{ 
                       	width: 310, template: "<a name='preview' href=''><span class='k-icon k-i-preview'></span>Preview</a>" +
                              "<a name='edit' href=''><span class='k-icon k-i-edit'></span>Edit</a>" +
                              "<a name='save' href=''><span class='k-icon k-i-save'></span>Save</a>" +
                              "<a name='destroy' href=''><span class='k-icon k-i-delete'></span>Delete</a>"
                    }
				],
				detailTemplate: function (data) {
                    return $("[name=details]", root).html()
                        .replace(/#:FieldsetTemplate#/g, () => kendo.htmlEncode(data.FieldsetTemplate))
                        .replace(/#:FieldTemplate#/g, () => kendo.htmlEncode(data.FieldTemplate));
                },
				detailExpand: function(e) {
					if($(e.detailRow).find(".CodeMirror").length === 0) {
						var theForm = this.dataItem(e.masterRow);
						var fsTemplateEditor = $(e.detailRow).find("textarea[name=fieldsetTemplate]");
						var fs = CodeMirror.fromTextArea(fsTemplateEditor[0],  getEditorConfig("htmlmixed"));
						fs.on("change", function() { 
							theForm.FieldsetTemplate = fs.getValue(); 
						});

                       var fTemplateEditor = $(e.detailRow).find("textarea[name=fieldTemplate]");
						var f = CodeMirror.fromTextArea(fTemplateEditor[0],  getEditorConfig("htmlmixed"));
						f.on("change", function() { 
							theForm.FieldTemplate = f.getValue(); 
						});
					}
				},
				dataBound: function() {
                    $("a[name=preview]", grid).on("click", FormManagement.preview);
                    $("a[name=edit]", grid).on("click", FormManagement.edit);
				    $("a[name=save]", grid).on("click", FormManagement.save);
					$("a[name=destroy]", grid).on("click", FormManagement.destroy);
				}
			});

			$("button[name=create]", grid).on("click", function(e) { FormManagement.newForm(e, app); });
		});
    },

   preview: function(e) {
      e.preventDefault();
   	  var root = $(".component[name=Forms]");
      var grid = $("[name=grid]", root).data("kendoGrid");
      var theForm = grid.dataItem($(e.currentTarget).closest("tr"));
      $(document.body).append($("<div name='formPreview' style='margin: 10px;'></div>"));
      var dialog = $("[name=formPreview]");
  	  var d = dialog.kendoWindow({
                visible: false,
                modal: true,
                resizable: false,
                title: theForm.Name,
                deactivate: function (e) {
                    this.destroy();
                },
       }).data("kendoWindow");
       api.call("Core/Form/Render()?theme=" + session.theme + "&culture=" + session.culture, theForm, function (result) {
            $(dialog).append(result.value);
            d.center();
			d.open();
       });
   },

    newForm: function(e, app) {
      var root = $(".component[name=Forms]");
      $(document.body).append($("<div name='formCreator'>" + $("[name=new]", root).html() + "</div>"));
      var dialog = $("[name=formCreator]");
  	  var d = dialog.kendoWindow({
                visible: false,
                modal: true,
                resizable: false,
                width: 510,
                title: "New Form",
                deactivate: function (e) {
                    this.destroy();
                },
           	}).data("kendoWindow");
			d.center();
			d.open();
      		$("button[name=create]", dialog).on("click", function() {
              $("button[name=create]", dialog).off("click");
               api.get("Core/Form/NewForm()", function(newForm) {
                  	newForm.AppId = app.Id;
                  	 newForm.Name = $("input[name=name]", dialog).val();
                     api.add("Core/Form", newForm, function(r) {
                           d.close();
                           notification.success('Form "' + newForm.Name + '" created.');
                           var grid = $(".component[name=Forms] [name=grid]").data("kendoGrid");
                           grid.dataSource.read();
                           grid.refresh();
                      });
               });
          });
    },

   edit: function(e) {
   		e.preventDefault();
        var root = $(".component[name=Forms]");
		var grid = $("[name=grid]", root).data("kendoGrid");
        var theForm = grid.dataItem($(e.currentTarget).closest("tr"));
        $(document.body).append($("<div name='designer'></div>"));
        var dialog = $("[name=designer]");
  	    var d = dialog.kendoWindow({
                visible: false,
                modal: true,
                resizable: false,
           		width: '95%',
           		height: '85%',
                title: "Form Designer",
                deactivate: function (e) {
                    this.destroy();
                },
          }).data("kendoWindow");
      	  loadComponent(dialog, "Form Builder", function(c) {
          	    FormBuilder.init(theForm);
             	d.center();
				d.open();
          });
   },

    save: function (e) {
        e.preventDefault();
		var root = $(".component[name=Forms]");
		var grid = $("[name=grid]", root).data("kendoGrid");
        var theForm = grid.dataItem($(e.currentTarget).closest("tr"));
        theForm.save(e, function () {
            notification.success("[resource_description[FormSaved]]");
        });
    },

    destroy: function (e) {
        e.preventDefault();
		var root = $(".component[name=Forms]");
		var grid = $("[name=grid]", root).data("kendoGrid");
        var theForm = grid.dataItem($(e.currentTarget).closest("tr"));
        theForm.destroy(e, function () {
            notification.success("[resource_description[FormDeleted]]");
            var grid = $(".component[name=Forms] [name=grid]").data("kendoGrid");
            grid.dataSource.read();
            grid.refresh();
        });
    }
};

