	formatProperty:function(prop){
		var scalar = type.ofProperty.isScalar(prop);

		// reformat before grid
		return {
			name: prop.Name,
			templateType:'',
			title: prop.Name,
			type: prop.ServerType,
			isScalar: scalar,
			// auto select all scalar properties
			selected: false,
			template:'#: '+prop.Name+' #',
			order:0,
			width:'auto',
			group:false,
			sort:false,
			hidden: false,
		};
	},

	formatChildProperty:function(prop){
		// reformat from grid
		return {
			name: prop.name,
			templateType:'',
			title:prop.title,
			selected: prop.selected,
			isScalar: prop.isScalar,
			template: prop.template,
			type: prop.type,
			order: prop.order,
			width:prop.width,
			group: prop.group,
