				{ title:'Group', template: function (data) { return "<input class=\"chkGrouped\" type=\"checkbox\" " + kendo.htmlEncode(data.group ? "checked" : "") + " " + kendo.htmlEncode(data.name ? "" : "disabled") + "/>"; }, width:50 },
				{ title:'Sort', template: function (data) { return "<input class=\"chkSort\" type=\"checkbox\" " + kendo.htmlEncode(data.sort ? "checked" : "") + " " + kendo.htmlEncode(data.name ? "" : "disabled") + "/>"; }, width:50 },
				{ title:'Hide', template: function (data) { return "<input class=\"chkHidden\" type=\"checkbox\" " + kendo.htmlEncode(data.hidden ? "checked" : "") + " " + kendo.htmlEncode(data.name ? "" : "disabled") + "/>"; }, width:50 },
				{ field: 'name', editor: GridBuilder.DisabledEditor, template:function (data) { return "" + kendo.htmlEncode(data.name ? data.name : "Custom") + ""; } },
				{ field: 'title', editor: GridBuilder.DefaultEditor },
