				{ width:50, title:'Currency', template: function (data) { return "<input type=\"radio\" name=\"" + kendo.htmlEncode(data.name) + "_template\" value=\"Currency\" " + kendo.htmlEncode(GridBuilder.checkTemplatetype(data.templateType, "currency")) + " />"; } },
				{ width:50, title:'Number', template: function (data) { return "<input type=\"radio\" name=\"" + kendo.htmlEncode(data.name) + "_template\" value=\"Number\" " + kendo.htmlEncode(GridBuilder.checkTemplatetype(data.templateType, "number")) + " />"; } },
				{ width:50, title:'Custom', template: function (data) { return "<input type=\"radio\" name=\"" + kendo.htmlEncode(data.name) + "_template\" value=\"Custom\" " + kendo.htmlEncode(GridBuilder.checkTemplatetype(data.templateType, "")) + " />"; } }
			],
