    "Script": "MonthlyBreakdownOfYearlyDiscounts = {
	init: async function (app, container) {
		app = app || session.app;
		container = container || $(".component[name=MonthlyBreakdownOfYearlyDiscounts]");

		var defaultCurrency = app.Config.B2B.DefaultCurrency
			? app.Config.B2B.DefaultCurrency
			: "EUR";
		var sourceSystem = app.Config.B2B.SourceSystem;

		$("[name=currencyDropdown]", container).kendoDropDownList({
			dataSource: app.Config.B2B.Currencies
				? app.Config.B2B.Currencies
				: ["USD", "EUR", "GBP"],
			change: async function (e) {
				var value = this.value();
				var data = await MonthlyBreakdownOfYearlyDiscounts.getData(app, months, value);
				chart.kendoObject.options.series[0].data = data;
				chart.kendoObject.options.series[0].name = `[resource_displayname[total]] (${value})`;
				chart.kendoObject.options.valueAxis.max = Math.max(...data) * 1.1;
				chart.kendoObject.refresh();

				if(data.flat().filter(d => d != 0).length == 0) {
					$('[name=nodata]', container).show();
					$('[name=chart]', container).hide();
				} else {
					$('[name=nodata]', container).hide();
					$('[name=chart]', container).show();
				}
			}
		});

		var oldestOffer = (await api.get(`B2B/Offer/FromSystem(SystemId='${sourceSystem}')?$select=DueDate&$orderby=DueDate asc&$top=1`)).value[0];
		var newestOffer = (await api.get(`B2B/Offer/FromSystem(SystemId='${sourceSystem}')?$select=DueDate&$orderby=DueDate desc&$top=1`)).value[0];

		var start = oldestOffer == null
			? new Date()
			: new Date(oldestOffer.DueDate);

		var end = newestOffer == null
			? new Date()
			: new Date(newestOffer.DueDate);

		var months = getMonthlyDateRange(start, end, 'MM-yyyy');

		$("[name=currencyDropdown]", container).data("kendoDropDownList").value(defaultCurrency);

		var data = await this.getData(app, months, defaultCurrency);

		var chart = this.initChart(container, months, data, defaultCurrency);
		chart.init();

		if(data.flat().filter(d => d != 0).length == 0) {
			$('[name=nodata]', container).show();
			$('[name=chart]', container).hide();
		} else {
			$('[name=nodata]', container).hide();
			$('[name=chart]', container).show();
		}

		$(window).resize(function () {
			$(chart.chartElement).data('kendoChart').refresh();
		});
	},

	initChart: function (container, months, data, currency) {
		var categories = months.map(m => m.formatted);

		var args = {
			showLegend: true,
			valueTemplate: function (data) { return "" + kendo.htmlEncode(kendo.toString(data.value, type.moneyFormat)) + ""; },
			tooltipTemplate: function (data) { return "" + (data.series.name) + ": " + (kendo.toString(data.value, type.moneyFormat)) + ""; },
			series: [{
				name: `[resource_displayname[total]] (${currency})`,
				data: data,
				line: {
					style: 'smooth'
				}
			}],
			categories: categories,
			max: Math.max(...data) * 1.1,
			type: "line"
		};

		return (new Chart($("[name=chart]", container), args));
	},

	getData: async function(app, months, currency) {
		var sourceSystem = app.Config.B2B.SourceSystem;
		var results = [];
		var data = [];

		for(var i = 0; i < months.length; i++) {
			(function(month) { // IIFE to capture the current month
				var endpoint = `B2B/Offer/FromSystem(SystemId='${sourceSystem}')`;
				var filter = `filter(DueDate gt ${month.from} and DueDate lt ${month.to} and CurrencyId eq '${currency}' and (FunderState eq 'FundingAccepted' or CreditorState eq 'FundingAccepted' or FunderState eq 'Paid'))`;
				data.push(api.get(`${endpoint}?$apply=${filter}/groupby((DueDate), aggregate(Id with countdistinct as Total, Cost with sum as Cost))`).then((r) => {
					if(r[0] == undefined) {
						r[0] = {
							CurrencyId: currency,
							Total: 0
						};
					}

					r.map(r => {
						r.CalendarMonth = month.formatted;
						return r;
					});

					results.push(...r);
				}));
			})(months[i]); // Pass the current month to the IIFE
		}

		await Promise.all(data);

		var categories = months.map(m => m.formatted);

		return categories.map(c => results.filter(d => d.CalendarMonth == c).map(r => r.Total).reduce((a, b) => a + b, 0));
	}
}",
